    17|import { ensureOperationalMemorySchema, listMemoryByCategory, upsertMemory } from './vector-memory';
    18|import { getOperationalSnapshot, type OperationalSnapshot } from './operational-adapters';
    19|import { OPERATIONAL_MEMORY_MARKER } from './memory-types';
    20|
    21|// ---------- Types ----------
    22|
    23|export type IncidentSeverity = 'low' | 'medium' | 'high' | 'critical';
    24|
    25|export type IncidentArea =
    26|  | 'deploy'
    27|  | 'api'
    28|  | 'queue'
    29|  | 'supabase'
    30|  | 'render'
    31|  | 'auth'
    32|  | 'latency'
    33|  | 'investor_workflow'
