    36|export type IncidentRecord = {
    37|  id: string;
    38|  area: IncidentArea;
    39|  severity: IncidentSeverity;
    40|  title: string;
    41|  summary: string;
    42|  rootCause: string;
    43|  signals: Record<string, unknown>;
    44|  detectedAt: string;
    45|};
    46|
    47|export type DecisionKind = 'patch' | 'rollback' | 'deploy' | 'gate' | 'note';
    48|
    49|export type DecisionRecord = {
    50|  id: string;
    51|  kind: DecisionKind;
    52|  title: string;
    53|  reason: string;
    54|  outcome: 'pending' | 'success' | 'failed' | 'blocked';
    55|  metadata: Record<string, unknown>;
    56|  decidedAt: string;
    57|};
    58|
    59|export type DeployRiskLevel = 'low' | 'medium' | 'high';
    60|
    61|export type DeployGateDecision = {
    62|  riskLevel: DeployRiskLevel;
    63|  confidence: number;
    64|  action: 'auto_deploy' | 'require_owner_approval' | 'blocked';
    65|  reasons: string[];
    66|  signals: {
    67|    openIncidents: number;
