    74|  marker: string;
    75|};
    76|
    77|export type FixOutcome = 'success' | 'failed' | 'partial' | 'rolled_back';
    78|
    79|export type FixOutcomeRecord = {
    80|  id: string;
    81|  taskId: string | null;
    82|  outcome: FixOutcome;
    83|  area: IncidentArea;
    84|  summary: string;
    85|  decidedAt: string;
    86|};
    87|
    88|// ---------- Telemetry table ----------
    89|
    90|function readTrimmed(value: unknown): string {
    91|  return typeof value === 'string' ? value.trim() : '';
    92|}
    93|
    94|function nowIso(): string {
    95|  return new Date().toISOString();
    96|}
    97|
    98|function getSupabaseRestBaseUrl(): string {
    99|  const url = readTrimmed(process.env.EXPO_PUBLIC_SUPABASE_URL).replace(/\/+$/, '');
   100|  if (!url) throw new Error('EXPO_PUBLIC_SUPABASE_URL is required for IVX engineering intelligence.');
   101|  return `${url}/rest/v1`;
   102|}
   103|
   104|function decodeJwtRole(token: string): string | null {
   105|  const seg = token.split('.')[1];
   106|  if (!seg) return null;
   107|  try {
   108|    const padded = seg.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(seg.length / 4) * 4, '=');
   109|    const parsed = JSON.parse(Buffer.from(padded, 'base64').toString('utf8')) as { role?: unknown };
   110|    return typeof parsed.role === 'string' ? parsed.role : null;
   111|  } catch { return null; }
   112|}
   113|
   114|function getServiceRoleKey(): string {
   115|  const anonKey = readTrimmed(process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY);
   116|  const key = readTrimmed(process.env.SUPABASE_SERVICE_ROLE_KEY) || readTrimmed(process.env.SUPABASE_SERVICE_KEY);
   117|  const role = decodeJwtRole(key);
   118|  if (!key || key === anonKey || (role !== 'service_role' && role !== 'supabase_admin')) {
   119|    throw new Error('A backend-only Supabase service-role key is required for engineering intelligence.');
   120|  }
   121|  return key;
   122|}
   123|
   124|function restHeaders(prefer?: string): HeadersInit {
   125|  const k = getServiceRoleKey();
   126|  return { apikey: k, Authorization: `Bearer ${k}`, 'Content-Type': 'application/json', ...(prefer ? { Prefer: prefer } : {}) };
   127|}
   128|
   129|async function rest<T>(path: string, init: RequestInit = {}, prefer?: string): Promise<T> {
   130|  const r = await fetch(`${getSupabaseRestBaseUrl()}${path}`, { ...init, headers: { ...restHeaders(prefer), ...(init.headers ?? {}) } });
   131|  const text = await r.text();
   132|  let payload: unknown = null;
   133|  if (text) { try { payload = JSON.parse(text); } catch { payload = { message: text.slice(0, 200) }; } }
   134|  if (!r.ok) {
   135|    const rec = (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload as Record<string, unknown> : {};
   136|    throw new Error(readTrimmed(rec.message) || readTrimmed(rec.error) || `HTTP ${r.status}`);
   137|  }
   138|  return payload as T;
   139|}
   140|
   141|async function execSql(sql: string): Promise<Record<string, unknown>> {
   142|  const payload = await rest<Record<string, unknown>>('/rpc/ivx_exec_sql', {
   143|    method: 'POST',
   144|    body: JSON.stringify({ sql_text: sql }),
   145|  });
   146|  return payload && typeof payload === 'object' ? payload : {};
   147|}
   148|
   149|let telemetrySchemaReady: Promise<void> | null = null;
   150|export async function ensureEngineeringIntelligenceSchema(): Promise<void> {
   151|  await ensureOperationalMemorySchema();
   152|  if (!telemetrySchemaReady) {
   153|    telemetrySchemaReady = (async () => {
   154|      const stmts = [
   155|        `create table if not exists public.ivx_telemetry (
   156|          id text primary key default gen_random_uuid()::text,
   157|          source text not null,
   158|          area text not null,
   159|          level text not null check (level in ('debug','info','warn','error','fatal')),
   160|          message text not null,
   161|          metadata jsonb not null default '{}'::jsonb,
   162|          created_at timestamptz not null default now()
   163|        )`,
   164|        `create index if not exists ivx_telemetry_area_idx on public.ivx_telemetry (area, created_at desc)`,
   165|        `create index if not exists ivx_telemetry_level_idx on public.ivx_telemetry (level, created_at desc)`,
   166|        `alter table public.ivx_telemetry enable row level security`,
   167|        `select pg_notify('pgrst','reload schema')`,
   168|      ];
   169|      for (const sql of stmts) {
   170|        const r = await execSql(sql);
   171|        if (r.ok === false) {
   172|          throw new Error(`Engineering intelligence schema setup failed: ${readTrimmed(r.error) || 'unknown'}`);
   173|        }
   174|      }
   175|    })().catch((error) => { telemetrySchemaReady = null; throw error; });
   176|  }
   177|  await telemetrySchemaReady;
   178|}
   179|
   180|// ---------- Telemetry ingestion ----------
   181|
   182|export type TelemetryLevel = 'debug' | 'info' | 'warn' | 'error' | 'fatal';
   183|
   184|export type TelemetryInput = {
   185|  source: string;
   186|  area: IncidentArea | string;
   187|  level: TelemetryLevel;
   188|  message: string;
   189|  metadata?: Record<string, unknown>;
   190|};
   191|
   192|export type TelemetryRow = TelemetryInput & { id: string; created_at: string };
   193|
   194|export async function ingestTelemetry(input: TelemetryInput): Promise<TelemetryRow> {
   195|  await ensureEngineeringIntelligenceSchema();
   196|  const payload = {
   197|    source: input.source.slice(0, 80) || 'unknown',
   198|    area: input.area.slice(0, 40) || 'unknown',
   199|    level: input.level,
   200|    message: input.message.slice(0, 2000) || '(empty)',
   201|    metadata: input.metadata ?? {},
   202|  };
   203|  const rows = await rest<unknown[]>('/ivx_telemetry?select=*', {
   204|    method: 'POST',
   205|    body: JSON.stringify(payload),
   206|  }, 'return=representation');
   207|  const row = Array.isArray(rows) ? rows[0] as Record<string, unknown> : null;
   208|  if (!row) throw new Error('Failed to insert telemetry row.');
   209|  return {
   210|    id: String(row.id ?? ''),
   211|    source: String(row.source ?? payload.source),
   212|    area: String(row.area ?? payload.area),
   213|    level: String(row.level ?? payload.level) as TelemetryLevel,
   214|    message: String(row.message ?? payload.message),
   215|    metadata: (row.metadata && typeof row.metadata === 'object' && !Array.isArray(row.metadata)) ? row.metadata as Record<string, unknown> : {},
   216|    created_at: String(row.created_at ?? nowIso()),
   217|  };
   218|}
   219|
   220|export type TelemetryStats = {
   221|  total: number;
   222|  errorRate: number;
   223|  byLevel: Record<string, number>;
   224|  byArea: Record<string, number>;
   225|  windowMinutes: number;
   226|};
   227|
   228|export async function getTelemetryStats(windowMinutes: number = 60): Promise<TelemetryStats> {
   229|  await ensureEngineeringIntelligenceSchema();
   230|  const minutes = Math.min(Math.max(Math.floor(windowMinutes), 1), 24 * 60);
   231|  const sql = `
   232|    with recent as (
   233|      select level, area from public.ivx_telemetry
   234|      where created_at > now() - interval '${minutes} minutes'
   235|    )
   236|    select
   237|      (select count(*) from recent)::int as total,
   238|      (select count(*) from recent where level in ('error','fatal'))::int as errors,
   239|      (select coalesce(json_object_agg(level, c), '{}'::json) from (select level, count(*)::int as c from recent group by level) s) as by_level,
   240|      (select coalesce(json_object_agg(area, c), '{}'::json) from (select area, count(*)::int as c from recent group by area) s) as by_area;
   241|  `;
   242|  const result = await execSql(sql);
   243|  const row = Array.isArray(result.rows) ? result.rows[0] as Record<string, unknown> : null;
   244|  const total = Number(row?.total ?? 0);
   245|  const errors = Number(row?.errors ?? 0);
   246|  const byLevel = (row?.by_level && typeof row.by_level === 'object' && !Array.isArray(row.by_level)) ? row.by_level as Record<string, number> : {};
   247|  const byArea = (row?.by_area && typeof row.by_area === 'object' && !Array.isArray(row.by_area)) ? row.by_area as Record<string, number> : {};
   248|  return {
   249|    total,
   250|    errorRate: total > 0 ? errors / total : 0,
   251|    byLevel,
   252|    byArea,
   253|    windowMinutes: minutes,
   254|  };
   255|}
