   276|
   277|function buildRootCause(area: IncidentArea, signal: Record<string, unknown>, snapshot: OperationalSnapshot): string {
   278|  const recentSha = snapshot.github.latestSha ? snapshot.github.latestSha.slice(0, 8) : 'unknown';
   279|  const renderStatus = snapshot.render.latestDeployStatus ?? 'unknown';
   280|  switch (area) {
   281|    case 'deploy':
   282|      return `Render deploy ${snapshot.render.latestDeployId ?? '?'} status=${renderStatus} on commit ${recentSha}. Likely cause: build/deploy failure or service suspension.`;
